package io.github.miklires.mclans.clan;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.entity.EntityDamageByEntityEvent;import org.bukkit.event.entity.PlayerDeathEvent;import org.bukkit.event.player.PlayerJoinEvent;public final class ClanListener implements Listener{private final ClanService service;public ClanListener(ClanService service){this.service=service;}@EventHandler public void join(PlayerJoinEvent e){service.refresh(e.getPlayer().getUniqueId());}@EventHandler(ignoreCancelled=true)public void damage(EntityDamageByEntityEvent e){if(e.getDamager() instanceof Player a&&e.getEntity() instanceof Player b&&service.blocksFriendlyFire(a.getUniqueId(),b.getUniqueId())){e.setCancelled(true);a.sendMessage(ClanService.color(service.text("&cFriendly fire is disabled.","&cУрон соклановцу отключён.")));}}@EventHandler public void death(PlayerDeathEvent e){Player killer=e.getPlayer().getKiller();if(killer!=null)service.awardKill(killer,e.getPlayer());}}
